DROP TABLE IF EXISTS `order_item_products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_item_products` (
  `order_item_product_id` bigint NOT NULL AUTO_INCREMENT,
  `order_item_id` int NOT NULL,
  `product_id` int NOT NULL,
  `ordered_quantity` int NOT NULL DEFAULT '1',
  `fulfilled_quantity` int NOT NULL DEFAULT '0',
  `product_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ORDERED',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`order_item_product_id`),
  UNIQUE KEY `uq_oip_item_product` (`order_item_id`,`product_id`),
  KEY `idx_oip_order_item` (`order_item_id`),
  KEY `idx_oip_product` (`product_id`),
  KEY `idx_oip_status` (`product_status`),
  CONSTRAINT `fk_oip_order_item` FOREIGN KEY (`order_item_id`) REFERENCES `order_items` (`order_item_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_oip_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_oip_fulfilled_quantity` CHECK ((`fulfilled_quantity` >= 0)),
  CONSTRAINT `chk_oip_ordered_quantity` CHECK ((`ordered_quantity` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=2001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

