--
-- Table structure for table `order_lifecycle_events`
--

DROP TABLE IF EXISTS `order_lifecycle_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_lifecycle_events` (
  `order_lifecycle_event_id` bigint NOT NULL AUTO_INCREMENT,
  `entity_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ORDER',
  `lifecycle_status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'STATUS_UPDATE',
  `order_id` int DEFAULT NULL,
  `order_item_product_id` bigint DEFAULT NULL,
  `box_id` int DEFAULT NULL,
  `conveyor_id` int DEFAULT NULL,
  `pallet_id` int DEFAULT NULL,
  `zone_id` int DEFAULT NULL,
  `dock_id` int DEFAULT NULL,
  `trailer_id` int DEFAULT NULL,
  `truck_id` int DEFAULT NULL,
  `trailer_dock_assignment_id` bigint DEFAULT NULL,
  `trailer_truck_assignment_id` bigint DEFAULT NULL,
  `event_source` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SYSTEM',
  `source_reference` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `confidence_score` decimal(5,2) DEFAULT NULL,
  `qr_read_success` tinyint(1) DEFAULT NULL,
  `severity` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NORMAL',
  `event_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `recorded_by` int DEFAULT NULL,
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
